  ui_story_31150601_5_dialog_content = "¿PlayerName?",
  ui_story_31150601_6_dialog_content = "No esperaba verte aquí.",
  ui_story_31150601_7_dialog_content = "¿Estoy interrumpiendo tus vacaciones?",
