  ui_story_31150601_16_dialog_content = "Simplemente me sentaré en esta silla vacía junto a ti.",
  ui_story_31150601_17_dialog_content = "¿Por qué decidiste ir de vacaciones de repente?",
  ui_story_31150601_18_dialog_content = "Jeje, ¿no puedes entender la idea de que un trabajador obsesivo de repente decida tomarse un descanso?",
  ui_story_31150601_19_dialog_content = "Para satisfacer las necesidades de entrega en Lumopolis, la Unión de Mensajería ha introducido recientemente algunos nuevos freelancers.",
  ui_story_31150601_20_dialog_content = "He estado dedicando mucho esfuerzo en entrenarlos.",
  ui_story_31150601_21_dialog_content = "Y un día, Wendy me encontró totalmente exhausto y desplomado en la entrada de la unión.",
  ui_story_31150601_22_dialog_content = "Entonces, Wendy me recomendó encarecidamente que me fuera de vacaciones, y entonces—",
  ui_story_31150601_23_dialog_content = "Como puedes ver, decidí venir a la playa para relajarme por un tiempo.",
  ui_story_31150601_24_dialog_content = "La forma en que siempre trabajas tan duro. Me hace sentir un poco avergonzado de mí mismo.",
  ui_story_31150601_25_dialog_content = "¿Estás tratando de halagarme?",
  ui_story_31150601_26_dialog_content = "En los ojos de esos novatos, no soy más que un fósil anticuado que se apega estrictamente a las reglas...",
  ui_story_31150601_27_dialog_content = "¿Qué paso?",
  ui_story_31150601_28_dialog_content = "Eres un miembro veterano de la Unión de Mensajería. Nunca pensé que los novatos se atreverían a ser tan groseros.",
  ui_story_31150601_29_dialog_content = "Por favor, no los culpes demasiado severamente.",
  ui_story_31150601_30_dialog_content = "Creo que quizás no estén totalmente equivocados...",
  ui_story_31150601_31_dialog_content = "<color=#e8d9bb>Hace un mes...</color>",
  ui_story_31150601_32_dialog_content = "Eso es todo para nuestras tareas recientes.",
  ui_story_31150601_33_dialog_content = "Por favor, preste atención al tiempo de entrega designado por el remitente.",
  ui_story_31150601_34_dialog_content = "Para cartas urgentes, es necesario que informes al remitente del tiempo más rápido posible.",
  ui_story_31150601_35_dialog_content = "Entregar dentro del tiempo acordado. No se permiten extensiones.",
  ui_story_31150601_36_dialog_content = "A veces, el remitente puede tener requisitos especiales con respecto al tiempo de entrega, así que por favor también preste atención a ellos.",
  ui_story_31150601_37_dialog_content = "Si aún tienes alguna pregunta, puedes venir a la unión y preguntarme en cualquier momento.",
  ui_story_31150601_38_dialog_content = "¡Tengo una pregunta!",
  ui_story_31150601_39_dialog_content = "Seguir.",
  ui_story_31150601_40_dialog_content = "Llevamos un mes aquí y recibimos todas estas solicitudes de entrega diariamente.",
  ui_story_31150601_41_dialog_content = "¿La Unión de Mensajería solo es capaz de proporcionar estos servicios de entrega anticuados?!",
  ui_story_31150601_42_dialog_content = "Si seguimos así, ¡eventualmente todos seremos eliminados!",
  ui_story_31150601_43_dialog_content = "Eliminado gradualmente...? Te refieres a...",
  ui_story_31150601_44_dialog_content = "¡Significa anticuado y obsoleto!",
  ui_story_31150601_45_dialog_content = "Muchas personas hoy en día ya no utilizan la Unión de Mensajería, esas pequeñas oficinas de correos también pueden satisfacer sus necesidades.",
  ui_story_31150601_46_dialog_content = "Cierto. La última vez que estaba en una entrega, el cliente me preguntó si la Unión de Mensajería ofrece algún otro tipo de servicio de correo...",
  ui_story_31150601_47_dialog_content = "¡Sí! ¡He tenido suficiente de esto durante el último mes! La forma en que hacemos entregas parece un fósil antiguo. ¡No pertenece al mundo moderno!",
  ui_story_31150601_48_dialog_content = "Y Pepi dijo que ya es bastante difícil simplemente entregar las cartas.",
  ui_story_31150601_49_dialog_content = "¡Exactamente!",
  ui_story_31150601_50_dialog_content = "¡Porque todos en la Unión de Mensajería sostienen esta idea, la unión pierde gradualmente su relevancia!",
  ui_story_31150601_51_dialog_content = "¿No estás de acuerdo, Lady Naroxel?",
  ui_story_31150601_52_dialog_content = "Consideraré cuidadosamente todo lo que has dicho.",
  ui_story_31150601_53_dialog_content = "Bueno, entonces, además de las tareas actuales de entrega, organizaré un nuevo trabajo para todos—",
  ui_story_31150601_54_dialog_content = "Cuando tengas tiempo, espero que todos puedan ayudar a recopilar opiniones del público.",
  ui_story_31150601_55_dialog_content = "Compila las experiencias de todos con el servicio de la Unión de Mensajería y organízalas en un libro de opiniones de usuarios.",
  ui_story_31150601_56_dialog_content = "Creo que podemos dejar las cosas así por hoy.",
  ui_story_31150601_57_dialog_content = "Así que eso fue lo que pasó.",
  ui_story_31150601_58_dialog_content = "Hmm...",
  ui_story_31150601_59_dialog_content = "¿También piensas... que soy un fósil viejo, sin lugar en el mundo moderno?",
  ui_story_31150601_60_option_content = "Creo que eres una PERSONA ocupada.",
  ui_story_31150601_61_dialog_content = "May Pregunto... ¿qué exactamente quieres decir con eso?",
  ui_story_31150601_62_dialog_content = "Bueno, como siempre estás tan ocupado, realmente no tienes tiempo para hacer otra cosa que entregar cartas.",
  ui_story_31150601_63_option_content = "¡Claro que no!",
  ui_story_31150601_64_dialog_content = "Cuando realmente lo pienso, teniendo en cuenta todo lo que sé sobre ti, sé que eres alguien dispuesto a cambiar con los tiempos.",
  ui_story_31150601_65_dialog_content = "Y un \"fósil\" es alguien terco y reacio a cambiar, ¿cierto?",
  ui_story_31150601_66_dialog_content = "Ya veo... Gracias.",
  ui_story_31150601_67_dialog_content = "Creo que necesito tu consejo.",
  ui_story_31150601_68_dialog_content = "En tus ojos, entregar cartas básicamente significa entregarlas a tiempo, ¿cierto?",
  ui_story_31150601_69_dialog_content = "Eso solía ser la única consideración cuando se trataba de entregar cartas—",
  ui_story_31150601_70_dialog_content = "Pero se han abierto nuevas posibilidades.",
  ui_story_31150601_71_dialog_content = "Creo que esos recién llegados estaban allí para recordarte esto.",
  ui_story_31150601_72_dialog_content = "Sí... Leí cuidadosamente las opiniones de los clientes que recogieron después de eso.",
  ui_story_31150601_73_dialog_content = "Nunca hubiera adivinado que el público tenía tantas opiniones sobre la unión antes de eso.",
  ui_story_31150601_74_dialog_content = "Es solo porque estás tan sumergido en tu trabajo que pasas por alto la posibilidad de desarrollo futuro.",
  ui_story_31150601_75_dialog_content = "Hace sentido...",
  ui_story_31150601_76_dialog_content = "Debería tomar un paso atrás de vez en cuando, como dijo Wendy...",
  ui_story_31150601_77_dialog_content = "De repente, me acuerdo de mi infancia en Northland.",
  ui_story_31150601_78_dialog_content = "El muelle con travesaños en verano... es tan diferente del paisaje de allí.",
  ui_story_31150601_79_dialog_content = "He estado yendo de un lado a otro, ocupándome con el trabajo todo este tiempo, ni siquiera he tomado realmente el tiempo para mirar bien el cielo azul encima de mí.",
  ui_story_31150601_80_dialog_content = "¡Me alegra que finalmente te hayas dado cuenta de eso!",
  ui_story_31150601_81_dialog_content = "Ya que todos estamos de vacaciones, no hablemos más del trabajo. ¡Disfrutemos simplemente de la diversión de estar junto al mar!",
  ui_story_31150601_82_dialog_content = "¿Qué tal si vamos a jugar en el agua?",
  ui_story_31150601_83_dialog_content = "Seguro...",
  ui_story_31150601_84_dialog_content = "Em... el agua está un poco fría.",
  ui_story_31150601_85_dialog_content = "Bueno, supongo que cuanto más caliente esté el tiempo, más fresco se siente el mar.",
  ui_story_31150601_86_dialog_content = "La sensación de flotar en el agua es tan relajante.",
  ui_story_31150601_87_dialog_content = "¿Eh? ¿Qué es esto?",
  ui_story_31150601_88_dialog_content = "¿Es esa una botella?",
  ui_story_31150601_89_dialog_content = "Parece que hay un mensaje enrollado dentro de él.",
  ui_story_31150601_90_dialog_content = "¡Ábrelo!",
  ui_story_31150601_91_dialog_content = "¿Debería?",
  ui_story_31150601_92_dialog_content = "¡Claro! ¡Es una carta sin mensajero! ¡Eso significa que cualquiera puede leerla!",
  ui_story_31150601_93_dialog_content = "Vamos a ver...",
  ui_story_31150601_94_dialog_content = "\"Mar hermoso hermoso, por favor cumple mi deseo de cumpleaños.\"",
  ui_story_31150601_95_dialog_content = "\"Espero que Mamá y Papá estén juntos para siempre y celebren mi cumpleaños cada año.\"",
  ui_story_31150601_96_dialog_content = "\"Si las cosas pudieran ser como son ahora... Sería tan feliz, ahora y siempre.\"",
  ui_story_31150601_97_dialog_content = "\"Querido querido mar, si es posible, quiero ser una superestrella también cuando crezca...\"",
  ui_story_31150601_98_dialog_content = "Pfffff—",
  ui_story_31150601_99_dialog_content = "Esta pequeña niña es muy linda.",
  ui_story_31150601_100_dialog_content = "Escribió tantos deseos. Me pregunto si alguno de ellos se hará realidad.",
  ui_story_31150601_101_dialog_content = "Jeje, estaré rezando por ella.",
  ui_story_31150601_102_dialog_content = "Así es. Las olas actuaron como mensajero de esta carta...",
  ui_story_31150601_103_dialog_content = "Esta botella no tiene recipiente, ya que solo representa los deseos de alguien.",
  ui_story_31150601_104_dialog_content = "Ya veo...",
  ui_story_31150601_105_dialog_content = "La Unión de Mensajería puede proporcionar más servicios según las necesidades de la gente—",
  ui_story_31150601_106_dialog_content = "Como mensajes en una botella.",
  ui_story_31150601_107_dialog_content = "Existen algunos métodos de correo únicamente por diversión.",
  ui_story_31150601_108_dialog_content = "La Unión de Mensajería puede proporcionar un servicio de mensaje en una botella sin un recipiente fijo para personas lejos del mar. Podría resultar ser un éxito.",
  ui_story_31150601_109_dialog_content = "Hmm, y si ampliamos aún más nuestro pensamiento...",
  ui_story_31150601_110_dialog_content = "También podemos establecer servicios de entrega de correo programados, como un servicio donde puedes enviar correo a tu yo futuro.",
  ui_story_31150601_111_dialog_content = "¡Oh! ¡Esta es el tipo de idea que solo podría venir de la mente de un mensajero experimentado! ¡Es realmente interesante!",
  ui_story_31150601_112_dialog_content = "Entregar cartas en diferentes momentos generará una experiencia distinta.",
  ui_story_31150601_113_dialog_content = "Creo que también podríamos organizar una actividad de emparejamiento de amigos por correspondencia anónimos—",
  ui_story_31150601_114_dialog_content = "Even personas sin cartas para enviar aún pueden encontrar una razón para comunicarse con otros a través de este tipo de actividad.",
  ui_story_31150601_115_dialog_content = "Confiar solo en el destino para unir a completos desconocidos. ¡Qué idea maravillosa!",
  ui_story_31150601_116_dialog_content = "Me has dado tantas ideas emocionantes, PlayerName.",
  ui_story_31150601_117_dialog_content = "Me gustaría agradecerte... por abrir mi mente.",
  ui_story_31150601_118_dialog_content = "Le contaré a todos sobre los nuevos arreglos de trabajo tan pronto como regrese a casa.",
  ui_story_31150601_119_dialog_content = "¡Y ahora, puedo disfrutar del resto de mi día festivo sin preocupaciones en el mundo!",
  ui_story_31150601_120_dialog_content = "Bueno, quizás no...",
  ui_story_31150601_121_dialog_content = "¿Mmm?",
  ui_story_31150601_122_dialog_content = "<color=#e8d9bb>Un borrón de plumas coloridas cae sobre la superficie del mar, mientras que Olive, la cabeza del espíritu cuclillo, queda atrapada en la botella que flota sobre las olas.</color>",
  ui_story_31150601_123_dialog_content = "<size=45>¡¡¡Oliva!!!</size>",
  ui_story_31150601_124_dialog_content = "¡Graznido!",
  ui_story_31150601_125_dialog_content = "Tú, pequeño pájaro curioso... ¿Puedes entender lo que está escrito en ese pedazo de papel?",
  ui_story_31150601_126_dialog_content = "Graznido—!!! ¡¡¡Graznido!!!",
  ui_story_31150601_127_dialog_content = "Espera, déjame ayudarte..."
}
return config
